#![feature(rustc_private)]
// SPDX-License-Identifier: MIT OR Apache-2.0
// Public safe imported metadata overflows while real SourceMap holds write lock.
// The real panic hook formats the same SourceMap, testing its locked branch.
use std::{cell::RefCell,fmt,fmt::Write,io,path::{Path,PathBuf},sync::{Arc,Mutex},panic::{catch_unwind,AssertUnwindSafe}};
use rustc_span::{FileName,SourceFile,SourceFileHashAlgorithm};
use rustc_span::def_id::CrateNum;
use rustc_span::source_map::{SourceMap,SourceMapInputs,FilePathMapping,FileLoader};
thread_local!{static CURRENT:RefCell<Option<Arc<SourceMap>>>=const{RefCell::new(None)};}
fn hex(s:impl AsRef<[u8]>)->String{s.as_ref().iter().map(|b|format!("{b:02x}")).collect()}
struct Loader;
impl FileLoader for Loader{fn file_exists(&self,_:&Path)->bool{true}fn read_file(&self,_:&Path)->io::Result<String>{Ok("".into())}fn read_binary_file(&self,_:&Path)->io::Result<Arc<[u8]>>{Ok(Arc::from(&b""[..]))}fn current_directory(&self)->io::Result<PathBuf>{Ok("/foo".into())}}
fn import(sm:&SourceMap,name:&str,length:u32){let f=SourceFile::new(FileName::Custom(name.into()),"".into(),SourceFileHashAlgorithm::Md5,None).unwrap();sm.new_imported_source_file(f.name,f.src_hash,f.checksum_hash,f.stable_id,length,f.unnormalized_source_len,CrateNum::from_u32(1),f.lines,f.multibyte_chars,f.normalized_pos,0);}
struct Sink{out:String,calls:Vec<String>,n:usize,fail:usize,address:String}
impl Write for Sink{fn write_str(&mut self,s:&str)->fmt::Result{self.n+=1;let normalized=if s==self.address{"<ptr>".into()}else if s==format!("0x{}",self.address){"0x<ptr>".into()}else{s.to_owned()};self.calls.push(format!("S:{}",hex(&normalized)));if self.n==self.fail{return Err(fmt::Error)}self.out.push_str(&normalized);Ok(())}fn write_char(&mut self,c:char)->fmt::Result{self.n+=1;self.calls.push(format!("C:{:x}",c as u32));if self.n==self.fail{return Err(fmt::Error)}self.out.push(c);Ok(())}}
struct Probe<'a>{map:&'a SourceMap,after:&'a RefCell<String>}
impl fmt::Debug for Probe<'_>{fn fmt(&self,f:&mut fmt::Formatter<'_>)->fmt::Result{let first=fmt::Debug::fmt(self.map,f);*self.after.borrow_mut()=format!("{}:{:?}:{:?}:{}:{:?}:{}:{}:{}",f.alternate(),f.width(),f.precision(),f.fill() as u32,f.align(),f.sign_plus(),f.sign_minus(),f.sign_aware_zero_pad());let second=fmt::Debug::fmt(&7u16,f);if first.is_ok()&&second.is_ok(){Ok(())}else{Err(fmt::Error)}}}
fn format(sink:&mut Sink,style:usize,value:&Probe<'_>)->fmt::Result{match style{0=>write!(sink,"{value:?}"),1=>write!(sink,"{value:#?}"),2=>write!(sink,"{value:*^12.3?}"),3=>write!(sink,"{value:+012?}"),4=>write!(sink,"{value:*<12?}"),5=>write!(sink,"{value:λ^12.3?}"),6=>write!(sink,"{value:x?}"),7=>write!(sink,"{value:#X?}"),8=>write!(sink,"{value:\0>12?}"),_=>unreachable!()}}
fn main(){rustc_data_structures::sync::set_dyn_thread_safe_mode(true);for style in 0..9{for fail in (0..=10).chain([20,40,60,80,120,160,240,320,400]){let sm=Arc::new(SourceMap::with_inputs(SourceMapInputs{file_loader:Box::new(Loader),path_mapping:FilePathMapping::empty(),hash_kind:SourceFileHashAlgorithm::Md5,checksum_hash_kind:None}));import(&sm,"locked-a",0);import(&sm,"locked-b",u32::MAX);let baseline=format!("{sm:?}");let prefix="<file_loader@0x";let start=baseline.find(prefix).unwrap()+prefix.len();let end=start+baseline[start..].find('>').unwrap();let address=baseline[start..end].to_string();let record=Arc::new(Mutex::new(String::new()));CURRENT.with(|current|*current.borrow_mut()=Some(Arc::clone(&sm)));let hook_record=Arc::clone(&record);std::panic::set_hook(Box::new(move|info|{let after=RefCell::new(String::new());let mut sink=Sink{out:String::new(),calls:vec![],n:0,fail,address:address.clone()};let good=CURRENT.with(|current|format(&mut sink,style,&Probe{map:current.borrow().as_ref().unwrap(),after:&after}).is_ok());let loc=info.location().unwrap();let kind=if info.payload().is::<String>(){"owned_string"}else{"static_str"};*hook_record.lock().unwrap()=format!("{}:{}:{}:{}:{}:{}:{}:{}:{}:{}",std::thread::panicking(),kind,loc.file(),loc.line(),loc.column(),hex(info.payload_as_str().unwrap_or("opaque")),good,hex(sink.out),hex(sink.calls.join("\n")),hex(after.into_inner()));}));let caught=catch_unwind(AssertUnwindSafe(||import(&sm,"locked-c",0))).is_err();std::panic::set_hook(Box::new(|_|{}));CURRENT.with(|current|*current.borrow_mut()=None);println!("{style}\t{fail}\t{caught}\t{}\t{}",hex(record.lock().unwrap().as_bytes()),sm.files().len());}}}
